    if (!organization?.id) return

    setIsLoading(true)
    setError(null)

    try {
      const supabase = createClient()

      // Build query with filters
      let query = supabase
        .from('audit_logs')
        .select('*', { count: 'exact' })
        .eq('organization_id', organization.id)
        .order('created_at', { ascending: false })

